import { readdir, readFile, access } from 'node:fs/promises'
import { join } from 'node:path'
import { gzipSync, brotliCompressSync } from 'node:zlib'
import { fileURLToPath } from 'node:url'

const distDir = new URL('../dist/', import.meta.url)
const distPath = fileURLToPath(distDir)
const assetsPath = join(distPath, 'assets')

// 1. Verify visualizer artifact
const statsHtmlPath = join(distPath, 'stats.html')
try {
  await access(statsHtmlPath)
} catch {
  console.warn('⚠️ Warning: dist/stats.html visualizer report not found.')
}

// 2. Read all generated JS bundles and precompressed artifacts
const allAssetFiles = await readdir(assetsPath)
const jsFiles = allAssetFiles.filter((file) => file.endsWith('.js'))
const brFiles = allAssetFiles.filter((file) => file.endsWith('.br'))
const gzFiles = allAssetFiles.filter((file) => file.endsWith('.gz'))

if (brFiles.length === 0) {
  console.error('❌ Error: No Brotli (.br) pre-compressed files generated by vite-plugin-compression!')
  process.exit(1)
}

// 3. Independent per-chunk budgets (in KiB)
const INDEPENDENT_CHUNK_BUDGETS = {
  'antd-icons': { label: 'AntD Icons', maxGzipKb: 25, maxRawKb: 70 },
  antd: { label: 'Ant Design Core', maxGzipKb: 330, maxRawKb: 1050 },
  echarts: { label: 'ECharts Visualization', maxGzipKb: 210, maxRawKb: 650 },
  react: { label: 'React Framework', maxGzipKb: 60, maxRawKb: 180 },
  markdown: { label: 'Markdown Parser', maxGzipKb: 55, maxRawKb: 175 },
  query: { label: 'TanStack Query', maxGzipKb: 20, maxRawKb: 55 },
  'rc-util': { label: 'RC Util Support', maxGzipKb: 15, maxRawKb: 30 },
  dayjs: { label: 'Dayjs Date Engine', maxGzipKb: 10, maxRawKb: 25 },
  index: { label: 'Application Entry', maxGzipKb: 45, maxRawKb: 120 },

  // Business route pages (strict budget to prevent code bloat in pages)
  businessRoute: { label: 'Business Route Page', maxGzipKb: 15, maxRawKb: 35 },

  // Shared small primitives / hooks
  primitive: { label: 'Shared Primitive / Hook', maxGzipKb: 10, maxRawKb: 20 },

  // Default fallback for any other chunk
  default: { label: 'General Chunk', maxGzipKb: 30, maxRawKb: 80 },
}

const routeChunkPattern =
  /^(?:Dashboard|StockList|Watchlist|StockChart|Screener|Strategies|DLPrediction|AgentAnalysis|AgentWorkspace|BacktestHistory)-/i

function getBudgetForChunk(filename) {
  for (const key of ['antd-icons', 'antd', 'echarts', 'react', 'markdown', 'query', 'rc-util', 'dayjs', 'index']) {
    if (filename.startsWith(key + '-') || filename === key + '.js') {
      return { key, ...INDEPENDENT_CHUNK_BUDGETS[key] }
    }
  }
  if (routeChunkPattern.test(filename)) {
    return { key: 'businessRoute', ...INDEPENDENT_CHUNK_BUDGETS.businessRoute }
  }
  return { key: 'primitive', ...INDEPENDENT_CHUNK_BUDGETS.primitive }
}

const stats = await Promise.all(
  jsFiles.map(async (file) => {
    const bytes = await readFile(join(assetsPath, file))
    const raw = bytes.byteLength
    const gzip = gzipSync(bytes).byteLength
    const brotli = brotliCompressSync(bytes).byteLength
    const budget = getBudgetForChunk(file)
    const rawKb = raw / 1024
    const gzipKb = gzip / 1024
    const brotliKb = brotli / 1024
    const passed = gzipKb <= budget.maxGzipKb && rawKb <= budget.maxRawKb
    return { file, rawKb, gzipKb, brotliKb, budget, passed }
  }),
)

console.log('\n📦 Chunk Budget Analysis (Independent Budgets):')
console.log('-----------------------------------------------------------------------------------------')
console.log(
  'Chunk File'.padEnd(35) +
  'Category'.padEnd(22) +
  'Gzip / Budget'.padEnd(20) +
  'Brotli'.padEnd(10) +
  'Status'
)
console.log('-----------------------------------------------------------------------------------------')

let hasFailure = false
for (const s of stats.sort((a, b) => b.gzipKb - a.gzipKb)) {
  const gzipStr = `${s.gzipKb.toFixed(1)} / ${s.budget.maxGzipKb} KB`
  const brotliStr = `${s.brotliKb.toFixed(1)} KB`
  const statusStr = s.passed ? '✅ PASS' : '❌ EXCEEDED'
  console.log(
    s.file.padEnd(35) +
    s.budget.label.padEnd(22) +
    gzipStr.padEnd(20) +
    brotliStr.padEnd(10) +
    statusStr
  )
  if (!s.passed) {
    hasFailure = true
  }
}
console.log('-----------------------------------------------------------------------------------------')

console.log(
  `🚀 Pre-compressed: ${brFiles.length} Brotli (.br) files, ${gzFiles.length} Gzip (.gz) files, Visualizer: dist/stats.html`
)

if (hasFailure) {
  console.error('\n❌ One or more chunks exceeded their independent budget threshold!\n')
  process.exit(1)
}

console.log('✨ All chunks passed their independent budgets!\n')
